window.__votdWeek && window.__votdWeek({"week":"2029-10-15","reading":"Doctrine and Covenants 115–120","days":[{"d":"2029-10-15","ref":"D&C 115:6","b":"D&C","c":115,"v":6,"he":"וְהִקָּבֵץ עַל־אֶרֶץ צִיּוֹן וְעַל יְתֵדוֹתֶיהָ יִהְיֶה לְמָעוֹז וּלְמַחְסֶה מִזֶּרֶם וּמֵחֵמָה אֲשֶׁר תִּשָּׁפֵךְ בְּלֹא־מֶזֶג עַל כׇּל־הָאָרֶץ׃","en":"And that the gathering together upon the land of Zion, and upon her stakes, may be for a defense, and for a refuge from the storm, and from wrath when it shall be poured out without mixture upon the whole earth."},{"d":"2029-10-16","ref":"D&C 115:7","b":"D&C","c":115,"v":7,"he":"תְּהִי הָעִיר פַּר וֶסְט אֶרֶץ קֹדֶשׁ וְהֻקְדְּשָׁה לִי וְתִקָּרֵא קֹדֶשׁ קׇדָשִׁים כִּי הָאֲדָמָה אֲשֶׁר אַתָּה עֹמֵד עָלֶיהָ קֹדֶשׁ הִיא׃","en":"Let the city, Far West, be a holy and consecrated land unto me; and it shall be called most holy, for the ground upon which thou standest is holy."},{"d":"2029-10-17","ref":"D&C 117:6","b":"D&C","c":117,"v":6,"he":"הֲלֹא לִי עוֹף הַשָּׁמַיִם וּדְגַת הַיָּם וְחַיַּת הֶהָרִים הֲלֹא אֲנִי עָשִׂיתִי אֶת־הָאָרֶץ הֲלֹא אֲנִי אֹחֵז בְּגוֹרָלוֹת כׇּל־צִבְאוֹת גּוֹיֵי הָאָרֶץ׃","en":"For have I not the fowls of heaven, and also the fish of the sea, and the beasts of the mountains? Have I not made the earth? Do I not hold the destinies of all the armies of the nations of the earth?"},{"d":"2029-10-18","ref":"D&C 117:7","b":"D&C","c":117,"v":7,"he":"לָכֵן הֲלֹא אַצְמִיחַ שְׁמָמוֹת וְאַפְרִיחַ אוֹתָן וְאוֹצִיא לָרֹב נְאֻם יְהוָה׃","en":"Therefore, will I not make solitary places to bud and to blossom, and to bring forth in abundance? saith the Lord."},{"d":"2029-10-19","ref":"D&C 118:1","b":"D&C","c":118,"v":1,"he":"אָמֵן כֹּה אָמַר יְהוָה יִקָּהֵל מוֹעֵד מַהֵר וְיֵעָרְכוּ הַשְּׁנֵים־עָשָׂר וְיִמָּנוּ אֲנָשִׁים לְמַלֵּא מְקוֹם הַנֹּפְלִים׃","en":"Verily, thus saith the Lord: Let a conference be held immediately; let the Twelve be organized; and let men be appointed to supply the place of those who are fallen."},{"d":"2029-10-20","ref":"D&C 119:1","b":"D&C","c":119,"v":1,"he":"אָמֵן כֹּה אָמַר יְהוָה אֲנִי דוֹרֵשׁ אֶת־כׇּל־עֹדֶף נִכְסֵיהֶם לָתֵת בְּיַד פָּקִיד כְּנֵסִיָּתִי בְּצִיּוֹן׃","en":"Verily, thus saith the Lord, I require all their surplus property to be put into the hands of the bishop of my church in Zion,"},{"d":"2029-10-21","ref":"D&C 119:4","b":"D&C","c":119,"v":4,"he":"וְאַחֲרֵי כֵן הַמְעֻשָּׂרִים יִתְּנוּ אֶחָד מֵעֲשָׂרָה מִכׇּל־תְּבוּאָתָם שָׁנָה בְשָׁנָה וְזֹאת תִּהְיֶה לָהֶם לְחֻקַּת עוֹלָם לִכְהֻנָּתִי הַקְּדוֹשָׁה נְאֻם יְהוָה׃","en":"And after that, those who have thus been tithed shall pay one-tenth of all their interest annually; and this shall be a standing law unto them forever, for my holy priesthood, saith the Lord."}]});
